package com.bananalab.lite;
import android.content.Context;import java.io.*;import java.util.*;import java.text.Normalizer;
/** Own small learned help-intent encoder; never emits executable instructions. */
final class ContextEncoder{
 final int inputs,hidden,classes;final float[] w1,b1,w2,b2;String[] labels;private static ContextEncoder cached;
 ContextEncoder(InputStream source,String[] names)throws Exception{try(DataInputStream in=new DataInputStream(source)){if(in.readInt()!=0x424e4c31)throw new IOException("Encoder incompatible");inputs=in.readInt();hidden=in.readInt();classes=in.readInt();if(inputs!=1024||hidden!=64||classes!=names.length||classes>32)throw new IOException("Encoder invalido");w1=read(in,inputs*hidden);b1=read(in,hidden);w2=read(in,hidden*classes);b2=read(in,classes);labels=names;}}
 static float[] read(DataInputStream in,int n)throws Exception{float[] out=new float[n];for(int i=0;i<n;i++){out[i]=in.readFloat();if(Float.isNaN(out[i])||Float.isInfinite(out[i]))throw new IOException("Pesos invalidos");}return out;}
 static float[] features(String text){String q=Normalizer.normalize(text.toLowerCase(java.util.Locale.ROOT),Normalizer.Form.NFD).replaceAll("\\p{M}","").replaceAll("[^a-z0-9 ]"," ").trim().replaceAll("\\s+"," ");if(q.length()>240)q=q.substring(0,240);q="^"+q+"$";float[] v=new float[1024];for(int n=3;n<=5;n++)for(int i=0;i+n<=q.length();i++){int h=0x811c9dc5;for(int j=0;j<n;j++)h=(h^q.charAt(i+j))*16777619;int at=(h&0x7fffffff)%1024;v[at]=Math.min(3,v[at]+1);}double norm=0;for(float a:v)norm+=a*a;norm=Math.sqrt(norm);if(norm>0)for(int i=0;i<v.length;i++)v[i]/=norm;return v;}
 float[] forward(float[] x){float[] h=b1.clone();for(int i=0;i<inputs;i++)if(x[i]!=0)for(int j=0;j<hidden;j++)h[j]+=x[i]*w1[i*hidden+j];float[] y=b2.clone();for(int j=0;j<hidden;j++)for(int k=0;k<classes;k++)y[k]+=Math.max(0,h[j])*w2[j*classes+k];return y;}
 String label(String q){float[] y=forward(features(q));int best=0;for(int i=1;i<classes;i++)if(y[i]>y[best])best=i;double sum=0;for(float v:y)sum+=Math.exp(v-y[best]);return 1/sum>=.85?labels[best]:"unknown";}
 static synchronized String classify(Context c,String q){try{if(cached==null){List<String> names=new ArrayList<>();try(BufferedReader r=new BufferedReader(new InputStreamReader(c.getAssets().open("context1/labels.txt"),"UTF-8"))){String line;while((line=r.readLine())!=null)if(!line.isEmpty())names.add(line);}cached=new ContextEncoder(c.getAssets().open("context1/context1.bin"),names.toArray(new String[0]));}return cached.label(q);}catch(Exception e){return "unknown";}}
}
